  str_quest_base_dayli_tips_awards_got = "Recompensas reclamadas",
  str_quest_base_story_new_chapter_open = "El nuevo capítulo de misión está disponible ahora",
  str_quest_base_daily_reset_tips = "Misión diaria ha sido restablecida",
  str_quest_base_awards_info_look = "Vista previa",
  str_quest_base_story_chapter_index = "Capítulo %s",
  str_quest_base_story_all_chapter_clean = "¡Todas las misiones de cap. completadas!",
  str_quest_base_story_current_chapter_clean = "Todas las mis. en este cap. se han completado",
  str_quest_base_story_click_lock_chapter = "Completa las mis. en la trama anterior para desb.",
  str_quest_base_desc_101 = "Soroz, este es el comienzo de tu viaje. Ganancias inesperadas, cambios, luces plateadas y crecimiento... Hacerse más fuerte siempre va acompañado de angustia. Si no puedes escapar de él, afróntalo. Tus sufrimientos no serán en vano.\n—Bethlehem",
  str_quest_base_desc_102 = "Llegar al mundo es una experiencia profunda, ¿verdad? Espero que enfrentes las crisis con calma y racionalidad, valorando tus lazos. Todos y todo lo que ves es parte de Astral, y finalmente se convertirá en parte de Aurora, incluso en parte de ti mismo... Acepta, comprende, responde y sigue creciendo.\n—Bethlehem",
  str_quest_base_desc_103 = "Los ecos del pasado resuenan de nuevo, con compatriotas, enemigos y camaradas en armas llegando en masa. Prepárate para lo peor y espera lo mejor. Sopesa tu odio personal frente a la misión de tu nuevo grupo. Estas lecciones solo se pueden aprender con sangre y lágrimas.\n—Bethlehem",
  str_quest_base_desc_104 = "Ahora, ¿entiendes tu objetivo? ¿Sientes un sentido de identidad de personas fuera de tu grupo? Adelante se encuentra la última ciudad Auroriana, una isla flotante en el cielo. Allí, encontrarás nuevos lazos y darás un paso más decidido hacia el viaje de superar la oscuridad.\n—Bethlehem",
  str_quest_base_desc_105 = "Constantemente frustrado pero siempre luchando, como una bestia que nunca sabe cómo retroceder, como un valiente que empuñó su espada pero murió en una tierra abandonada. El pasado seguirá avanzando, enfrentándote a tus mayores miedos. Mírala a la cara y dime: ¿A quién ves?\n—Bethlehem",
  str_quest_base_desc_106 = "¿Ansioso? Como sugiere la Aurora, estás cerca del fondo, un lodazal de amargura y resentimiento, una prisión de hierro construida de fracaso y humillación. Pero solo aquí puedes encontrar la verdadera fuerza, no acero y hierro, sino una visión amplia y una mente inclusiva.\n—Bethlehem",
  str_quest_base_desc_107 = "Finalmente entramos en una nueva fase de nuestra conversación interespacial, Caelestite. Nunca entenderías mi papel, ni yo los fragmentos de palabras escritas como vagos presagios. Aurora se debilita y hombres desesperados con alas extendidas llenan los cielos de Lumopolis. O lo conquistas o serás conquistado, fin de la historia.\n—Bethlehem",
  str_quest_base_desc_108 = "Incluso en el abismo más profundo y oscuro, sobrevivirás para ver el cumplimiento de la profecía. Eso es lo que creo, y mi intuición insiste en que sigo. ¡Aprovecha la oportunidad, Caelestite, y condena al negro a quedarse donde pertenecía!\n—Bethlehem",
  str_quest_base_desc_109 = "Tenemos dos viviendas: El que está debajo de tus pies y el que está en tu corazón. Los afortunados entre nosotros encontrarán que no hay diferencia entre ellos. Sin embargo, la mayoría de las almas deben soportar un conflicto constante entre los dos, e incluso pueden quedarse sin la esperanza de volver a poner los pies en la tierra en lo profundo de sus recuerdos. Incluso si el corazón no está dispuesto a seguir adelante, no hay otra manera.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_110 = "Creo que la tierra te permitirá crecer, recordándote muchas cosas mientras te permite hacer las paces con calma con ellas. El final de tu viaje está por venir. Desecha tu resentimiento y odio, y déjalo desaparecer. Espero que la próxima vez que nos veamos, seas un nuevo tú.\n                                                                                                                       —Bethlehem",
  str_quest_base_desc_111 = "La noche eterna, el territorio al que ningún auroriano quiere acercarse, es un abismo erosionado por la oscuridad. En este Interludio Crepuscular, aprovecha la fugaz oportunidad, maestro del Coloso, para atravesar la oscuridad. Que tu deseo se cumpla.\n\n-- Belén",
  str_quest_base_desc_112 = "La esperanza suele ir acompañada de pruebas, como una flor cubierta de espinas. Si estás preparado para ser magullado y maltratado, regresa al punto de partida. Buscar, perder, desesperar y finalmente levantar la cabeza una vez más.\n\n—Bethlehem",
  str_quest_base_desc_113 = "La hoja de la verdad atraviesa el pecho de uno, desgarrando en pedazos el frágil corazón interior. \"¿Cómo puede ser esto?\" \"¡No puede ser!\" Conmoción, duda, resentimiento y luego mirar al vacío junto al abismo perdido. No puedo ver tu elección, Caelestite, no puedo ver nada.\n\n—— Bethlehem",
  str_quest_base_desc_114 = "Todo el mundo está constantemente buscando conocimiento en su vida. Eres afortunado, pero también lamentable. El destino te ha dado más espacio para explorar. Puedes ir más lejos que la mayoría de la gente, pero es un viaje solitario. No sé dónde terminarás, porque tu destino está más allá de lo que puedo ver.\n—Belén",
  str_quest_base_desc_115 = "¿Has notado que estás empezando a conocer a más y más gente? Tienen diferentes orígenes y destinos, pero sus caminos coinciden con los tuyos en un determinado momento. Mucha gente vive bajo el cielo. Los afortunados con el sol sobre sus cabezas están bañados por la luz solar más abundante, pero los que se paran en el crepúsculo son los más alejados del sol.\n—Belén",
  str_quest_base_desc_116 = "Qué irónico giro del destino es este que te obliga a estar junto a un viejo enemigo. Ya sea un mar de llamas o un pozo profundo, no hay más remedio que enfrentarlo con tus amigos.\n—Bethlehem",
  str_quest_base_desc_117 = "El campo de batalla es un escenario para intrigantes, y los espectadores ignorantes acuden a él desde todas las direcciones. La noche sin límites se acerca, pero los aurorianos no han despertado de sus dulces sueños.\n—Bethlehem",
  str_quest_base_desc_118 = "En medio de las cambiantes mareas del poder, aquellos a quienes el destino ha pasado por alto se alzan en el escenario mundial bajo la mirada de muchos. Sin embargo, la ambición resulta ser el arma más inútil en el campo de batalla: solo al vencer a su antiguo yo, uno puede escapar del remolino de la política y obtener una vida renovada.\n—Bethlehem",
  str_quest_base_desc_119 = "¿La fuerza proviene de la autopropulsión o de la concesión de otros? Hasta que presencies formas poderosas luchando en el fango, cavando sus propias tumbas, finalmente te darás cuenta de que la fragilidad es la esencia de la vida.\n—Bethlehem",
  str_quest_base_desc_120 = "Una existencia extranjera finalmente hizo contacto con Illumina después de más de 600 años. ¿Deberíamos voltear las páginas de los libros de historia en busca de posibilidades, o deberíamos abandonar el pasado y forjar un nuevo camino? Esa es la pregunta en cuestión, así como un enigma que ha perturbado a innumerables generaciones de Aurorianos.\n—Bethlehem",
  str_quest_base_desc_121 = "Has pasado incontables horas de felicidad con tus amigos, pero nunca pensaste que el momento de decir adiós llegaría tan precipitadamente. La señal del pasado ha regresado. Esta vez, debes volverte fuerte y explorar tu pasado en las ruinas desconocidas.\n—Bethlehem",
  str_quest_base_desc_122 = "\"Para erigir faros a lo largo del camino por delante\", así hablé yo, el Queen del Norte.\n—Bethlehem",
  str_quest_base_type_stroy_with_space = "Historia",
