  str_quest_base_achieve_type_407_space = "Colossus",
  str_quest_base_achieve_finish_list_title = "Misiones completadas",
  str_quest_base_desc_123 = "Ahora has presenciado la noche eterna, ¿has solidificado la resolución en tu corazón? Innumerables almas están atrapadas en un punto muerto de sombras, persiguiendo una esperanza fugaz. Pero para ti, esa esperanza es real.\nLa aprovecharás, porque este cuento comienza con tus primeros pasos como héroe. Deberás proteger esa chispa de esperanza, y a cambio, perdurará gracias a ti. Cree en esto, y avanza con una fe inquebrantable.\n—Bethlehem",
